package com.chubb.apac.claims.modulith.assessment.controller;import com.chubb.apac.claims.modulith.assessment.dto.request.*;import com.chubb.apac.claims.modulith.assessment.dto.response.*;import com.chubb.apac.claims.modulith.assessment.service.AssessmentService;import com.chubb.apac.claims.modulith.common.dto.ApiResponse;import com.chubb.apac.claims.modulith.common.security.CurrentUser;import com.chubb.apac.claims.modulith.common.util.CorrelationId;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/staff/assessments") @PreAuthorize("hasRole('CLAIMS_STAFF')")
public class StaffAssessmentController{private final AssessmentService service;public StaffAssessmentController(AssessmentService s){service=s;}@PostMapping("/{claimId}")public ResponseEntity<ApiResponse<AssessmentResponse>> submit(@AuthenticationPrincipal CurrentUser u,@PathVariable String claimId,@RequestHeader(value=CorrelationId.HEADER,required=false)String correlation,@Valid @RequestBody SubmitAssessmentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.submit(claimId,u.userId(),u.markets(),correlation,r)));}@GetMapping("/{claimId}")public ApiResponse<AssessmentResponse> get(@AuthenticationPrincipal CurrentUser u,@PathVariable String claimId){return ApiResponse.success(service.get(claimId,u.userId(),u.markets()));}@PutMapping("/{claimId}")public ApiResponse<AssessmentResponse> update(@AuthenticationPrincipal CurrentUser u,@PathVariable String claimId,@Valid @RequestBody UpdateAssessmentRequest r){return ApiResponse.success(service.update(claimId,u.userId(),u.markets(),r));}@PostMapping("/{claimId}/validate")public ApiResponse<AssessmentValidationResponse> validate(@AuthenticationPrincipal CurrentUser u,@PathVariable String claimId,@RequestHeader(value=CorrelationId.HEADER,required=false)String correlation){return ApiResponse.success(service.validate(claimId,u.userId(),u.markets(),correlation));}}
